query.sql:
WITH sample_users AS (
  SELECT 1 AS id, 'Alice' AS name, 25 AS age, 'IT' AS department, 'active' AS status,
         datetime('now', '-30 days') AS created_at
  UNION ALL SELECT 2, 'Bob', 32, 'HR', 'active', datetime('now', '-25 days')
  UNION ALL SELECT 3, 'Charlie', 28, 'Finance', 'inactive', datetime('now', '-20 days')
  UNION ALL SELECT 4, 'Diana', 35, 'IT', 'active', datetime('now', '-15 days')
  UNION ALL SELECT 5, 'Eve', 29, 'HR', 'active', datetime('now', '-10 days')
  UNION ALL SELECT 6, 'Frank', 42, 'Finance', 'inactive', datetime('now', '-5 days')
  UNION ALL SELECT 7, 'Grace', 26, 'IT', 'active', datetime('now', '-2 days')
)
SELECT id, name, age, department, status, created_at,
       {{ (search_keyword or '') | sql_quote }} AS search_term
FROM sample_users
WHERE 1 = 1
{% if not include_inactive %}
  AND status = {{ user_status | sql_quote }}
{% endif %}
  AND age BETWEEN {{ min_age }} AND {{ max_age }}
{% if departments %}
  AND department IN {{ departments | sql_in }}
{% endif %}
{% if user_ids %}
  AND id IN {{ user_ids | sql_in }}
{% endif %}
{% for key, value in filters.items() %}
  -- filter {{ loop.index }}: {{ key }} = {{ value }} (illustration only)
{% endfor %}
{% if search_keyword is not none and search_keyword | trim %}
  AND (name LIKE {{ ('%' ~ search_keyword ~ '%') | sql_quote }}
       OR department LIKE {{ ('%' ~ search_keyword ~ '%') | sql_quote }})
{% endif %}
ORDER BY created_at DESC
LIMIT {{ limit | sql_limit }}
